  const out = [];
  const nums = lines[0].slice(1, -1).split(',').map(Number);
  const n = nums.length;
  for (let i = 0; i < n; i++) {
    while (nums[i] > 0 && nums[i] <= n && nums[nums[i] - 1] !== nums[i]) {
      const temp = nums[i];
      nums[i] = nums[temp - 1];
      nums[temp - 1] = temp;
    }
  }
  for (let i = 0; i < n; i++) {
    if (nums[i] !== i + 1) {
      out.push(i + 1);
      return out;
    }
  }
  out.push(n + 1);
  return out;
